/* dg_brick.h -- 128x128 ARGB8888 stone-wall tile for LVGL bg_image_tiled().
 *
 * Generated by tools/gen_brick_tile.py.  Irregular staggered courses with
 * jittered mortar, drawn rather than cropped: the retail artwork's stones are
 * far too large for a 320x240 panel and its seams do not tile.  Mortar is mid
 * grey with alpha, so the shell colour picked in the menu shows through and
 * every colourway gets the same wall.  Grey means R=G=B, so ARGB8888 byte order
 * cannot tint it.  128x128x4 = 64 KB of flash (was 192x192 = 147 KB). */
